select commitment.project_id::text, sum(valor_empenho)::numeric as valor_empenho, sum(aliquidar)::numeric as aliquidar, sum(liquidado)::numeric as liquidado, sum(pago)::numeric as pago, sum(rpinscrito)::numeric as rpinscrito, sum(rpaliquidar)::numeric as rpaliquidar, sum(rpaliquidado)::numeric as rpaliquidado, sum(rppago)::numeric as rppago, count(*)::bigint as commitment_count, max(commitment.source_updated_at)::timestamptz as source_updated_at, max(commitment.ingested_at)::timestamptz as ingested_at, commitment.ingestion_id::uuid
from {{ ref('fct_commitment') }} commitment inner join {{ ref('int_obrasgov_current_ingestion') }} current on commitment.ingestion_id=current.ingestion_id group by commitment.project_id, commitment.ingestion_id
